 *  their statements: how many have been taken, and the last one's due-total and date (none until the
 *  first), and the date they are retired from (null: not retired; set at all, they count as retired),
 *  and their holds, by when they were added (a held person gets no cut of a pool; their claims still
 *  count in every total), and from their retirement date on their open claims not bound by a statement
 *  count in no live total. */
public class Person {
    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    /** The grades they were given, by from-date (none first). */
    private java.util.List<GradeFrom> grades = new java.util.ArrayList<>();
    /** The grade this request's save records (null: none). */
    private GradeFrom recorded;
    /** Their own terms in whole days from the beginning of time (null: none). */
    private Integer terms;
    /** Their own terms given from a from-date, by from-date. */
    private java.util.List<TermsFrom> datedTerms = new java.util.ArrayList<>();
    /** The dated terms this request's save records (null: none). */
    private TermsFrom recordedTerms;
    /** Whether this request's save changed their terms, for its audit line. */
    private boolean termsChanged;
    /** Their contact, trimmed and lower-cased (null: none). */
    private String contact;
    /** Whether this request's save changed their contact, for its audit line. */
    private boolean contactChanged;
    /** Their tags, sorted and comma separated (null: none). */
    private String tags;
    private long version;
    private int statementCount;
    private String statedTotal;
    private String statementDate;
    private String retiredFrom;
    /** Their past retirements, oldest first. */
    private java.util.List<Retirement> retirements = new java.util.ArrayList<>();
    /** The SNAPSHOTs written for them, oldest first. */
    private java.util.List<Snapshot> snapshots = new java.util.ArrayList<>();
    /** Their statements still standing, oldest first (in the order taken). */
    private java.util.List<StatementLine> statements = new java.util.ArrayList<>();
    /** Their holds, in the order they were added. */
    private java.util.List<Hold> holds = new java.util.ArrayList<>();
    /** The sheet's today (null: not known). */
    private java.time.LocalDate today;
    /** The ids of the people they name as patrons, in the order named. */
    private java.util.List<Long> patronIds = new java.util.ArrayList<>();
    /** Their aliases, sorted as names are compared. */
    private java.util.List<String> aliases = new java.util.ArrayList<>();
    /** The date the statement this request took was taken as of (null: now), for its audit line. */
    private String statedAsOf;
    /** How many claims the statement this request took bound, for its audit line. */
    private int statedClaims;
    /** The due-total of the statement this request cancelled, for its audit line. */
    private String cancelledTotal;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this(id, sheetId, name, grade, version, 0, null, null);
    }

    public Person(long id, String sheetId, String name, String grade, long version,
            int statementCount, String statedTotal, String statementDate) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
        this.statementCount = statementCount;
        this.statedTotal = statedTotal;
        this.statementDate = statementDate;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getGrade() { return grade; }
    public java.util.List<GradeFrom> getGrades() { return grades; }

    /** Their grades, by from-date (none first), and the one in force on the sheet's today. */
    public void setGrades(java.util.List<GradeFrom> grades, java.time.LocalDate today) {
        this.grades = grades;
        this.grade = gradeOn(today.toString());
        this.today = today;
    }

    /** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before
     *  it; null when there is none. */
    public String gradeOn(String date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && g.from().compareTo(date) > 0) continue;
            if (found == null || (found.from() == null ? "" : found.from()).compareTo(g.from() == null ? "" : g.from()) < 0) found = g;
        }
        return found == null ? null : found.grade();
    }

    /** Give them the grade from the from-date (null: the beginning of time), replacing the one
     *  with the same from-date; the save records it. */
    public void giveGrade(String grade, String from, java.time.LocalDate today) {
        java.util.List<GradeFrom> now = new java.util.ArrayList<>(grades);
        now.removeIf((g) -> java.util.Objects.equals(g.from(), from));
        now.add(new GradeFrom(grade, from));
        now.sort(java.util.Comparator.comparing((GradeFrom g) -> g.from() == null ? "" : g.from()));
        setGrades(now, today);
        recorded = new GradeFrom(grade, from);
    }

    /** Their own terms in force on the sheet's today (null: none). */
    public Integer getTerms() { return today == null ? terms : termsOn(today.toString()); }
    /** Their own terms from the beginning of time (null: none). */
    public Integer getBaseTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    public java.util.List<TermsFrom> getDatedTerms() { return datedTerms; }
    public void setDatedTerms(java.util.List<TermsFrom> datedTerms) { this.datedTerms = datedTerms; }

    /** Their own terms in force on the date (yyyy-MM-dd): the dated ones with the latest from-date on
     *  or before it, else those from the beginning of time (null: none). */
    public Integer termsOn(String date) {
        TermsFrom found = null;
        for (TermsFrom t : datedTerms) {
            if (t.from().compareTo(date) > 0) continue;
            if (found == null || found.from().compareTo(t.from()) < 0) found = t;
        }
        return found == null ? terms : found.terms();
    }

    /** Give them these terms (null: none) from the from-date, replacing those with the same from-date;
     *  the save records them, and the audit line records the terms in force when they changed. */
    public void giveTermsFrom(Integer terms, String from) {
        TermsFrom was = datedTerms.stream().filter((t) -> t.from().equals(from)).findFirst().orElse(null);
        termsChanged = was == null || !java.util.Objects.equals(was.terms(), terms);
        java.util.List<TermsFrom> now = new java.util.ArrayList<>(datedTerms);
        now.removeIf((t) -> t.from().equals(from));
        now.add(new TermsFrom(terms, from));
        now.sort(java.util.Comparator.comparing(TermsFrom::from));
        datedTerms = now;
        recordedTerms = new TermsFrom(terms, from);
    }

    @JsonIgnore
    public TermsFrom getRecordedTerms() { return recordedTerms; }

    /** Give them these terms (null: none); the audit line records them when they changed. */
    public void giveTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }

    @JsonIgnore
    public boolean isTermsChanged() { return termsChanged; }

    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }

    /** Give them this contact (null: none); the audit line records it when it changed. */
    public void giveContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }

    @JsonIgnore
    public boolean isContactChanged() { return contactChanged; }

    /** Their tags, sorted and comma separated (null: none). */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }

    @JsonIgnore
    public GradeFrom getRecorded() { return recorded; }
    public long getVersion() { return version; }
    public void setVersion(long version) { this.version = version; }
    public int getStatementCount() { return statementCount; }
    public String getStatedTotal() { return statedTotal; }
    public String getStatementDate() { return statementDate; }
    public String getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(String retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    public java.util.List<Retirement> getRetirements() { return retirements; }
    public void setRetirements(java.util.List<Retirement> retirements) { this.retirements = retirements; }
    public java.util.List<Snapshot> getSnapshots() { return snapshots; }
    public void setSnapshots(java.util.List<Snapshot> snapshots) { this.snapshots = snapshots; }
    public java.util.List<StatementLine> getStatements() { return statements; }
    public void setStatements(java.util.List<StatementLine> statements) { this.statements = statements; }

    /** Unretire them on the date: no longer retired, the retirement kept as a past one up to it. */
    public void unretire(String on) {
        retirements.add(new Retirement(retiredFrom, on));
        retiredFrom = null;
    }
    /** Whether the sheet's today is on or after their retirement date: their open claims no statement
     *  bound then count in no live total. */
    public boolean isRetiredReached() {
        return retiredFrom != null && today != null && !today.isBefore(java.time.LocalDate.parse(retiredFrom));
    }
    /** Whether they have any hold. */
    public boolean isHeld() { return !holds.isEmpty(); }
    public java.util.List<Hold> getHolds() { return holds; }
    public void setHolds(java.util.List<Hold> holds) { this.holds = holds; }
    public java.util.List<Long> getPatronIds() { return patronIds; }
    public void setPatronIds(java.util.List<Long> patronIds) { this.patronIds = patronIds; }
    public java.util.List<String> getAliases() { return aliases; }
    public void setAliases(java.util.List<String> aliases) { this.aliases = aliases; }
    /** The sheet they were last transferred from (null: none). */
    private String origin;
    public String getOrigin() { return origin; }
    public void setOrigin(String origin) { this.origin = origin; }
    /** The sheet's today a transfer brought them here on (null: they did not arrive by transfer). */
    private String arrivedOn;
    public String getArrivedOn() { return arrivedOn; }
    public void setArrivedOn(String arrivedOn) { this.arrivedOn = arrivedOn; }
    /** Whether their name or an alias is used, as a name or alias, on another sheet of the sheet's tree. */
    private boolean clashing;
    public boolean isClashing() { return clashing; }
    public void setClashing(boolean clashing) { this.clashing = clashing; }

    /** Whether the claim counts in live totals: it counts by status, and is not an open (OPEN or
     *  PENDING) claim of a person whose retirement date is reached that no statement bound, nor a
     *  deferred one. A hold (theirs or the claim's own) leaves nothing out: it only matters in the pools. */
    public boolean countsLive(Claim claim) {
        return claim.isCounting() && !leftOutLive(claim);
    }

    /** Whether the claim counts in claimed (and the claimed-total): as {@link #countsLive}. */
    public boolean countsClaimed(Claim claim) {
        return claim.isCounting() && !claim.isDeferred()
                && !(ClaimStatus.isOpen(claim.getStatus()) && !claim.isStated() && isRetiredReached());
    }

    /** Whether the live rules leave the claim out whatever its status counts: it is deferred, or an
     *  open (OPEN or PENDING) claim that no statement bound of a person whose retirement date the
     *  sheet's today has reached. */
    public boolean leftOutLive(Claim claim) {
        return claim.isDeferred()
                || (ClaimStatus.isOpen(claim.getStatus()) && !claim.isStated() && isRetiredReached());
    }

    /** Whether a claim on this date is refused: the person is retired from a date before it, or it
     *  is dated after the from and before the to of one of their past retirements. */
    public boolean retiredBefore(java.time.LocalDate date) {
        return (retiredFrom != null && date.isAfter(java.time.LocalDate.parse(retiredFrom)))
                || retirements.stream().anyMatch((r) -> r.refuses(date));
    }

    /** Record a statement just taken: its due-total (null: n/a), date and how many claims it bound. */
    public void stated(String total, String date, int claims) {
        this.statementCount++;
        this.statedTotal = total == null ? "n/a" : total;
        this.statementDate = date;
        this.statedClaims = claims;
    }

    /** Take on the statements of a person merged into them: the count becomes theirs plus the other's;
     *  their last statement stays theirs (having none, it becomes the other's). */
    public void absorbStatements(Person from) {
        if (this.statementCount <= 0 || this.statementDate == null) {
            this.statedTotal = from.statedTotal;
            this.statementDate = from.statementDate;
        }
        this.statementCount += from.statementCount;
    }

    /** Cancel their last statement: the count goes down by one and they show the one before it
     *  (null total and date: none), keeping the cancelled one's due-total for its audit line. */
    public void unstated(String total, String date) {
        this.cancelledTotal = this.statedTotal;
        this.statementCount--;
        this.statedTotal = date == null ? null : total == null ? "n/a" : total;
        this.statementDate = date;
    }

    @JsonIgnore
    public String getCancelledTotal() { return cancelledTotal; }

    @JsonIgnore
    public int getStatedClaims() { return statedClaims; }

    @JsonIgnore
    public String getStatedAsOf() { return statedAsOf; }
    public void setStatedAsOf(String statedAsOf) { this.statedAsOf = statedAsOf; }

    /** Their flag's reason and until-date (yyyy-MM-dd; both null: never flagged). */
    private String flagReason;
    private String flagUntil;
    @JsonIgnore
    public String getFlagReason() { return flagReason; }
    @JsonIgnore
    public String getFlagUntil() { return flagUntil; }
    public void setFlag(String reason, String until) {
        this.flagReason = reason;
        this.flagUntil = until;
    }
    /** Whether their flag is in force: the sheet's today is on or before its until-date. */
    @JsonIgnore
    public boolean isFlagged() {
        return flagUntil != null && today != null && today.toString().compareTo(flagUntil) <= 0;
    }
    /** The reason their flag shows while it is in force (null: none). */
    public String getFlagShown() { return isFlagged() ? flagReason : null; }

    /** The user who may approve or reject their PENDING claims as a steward may (null: none). */
    private String approver;
    public String getApprover() { return approver; }
    public void setApprover(String approver) { this.approver = approver; }
}

package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class PersonRepository {

    private static final String COLUMNS = "id, sheet_id, name, version, statement_count, stated_total, statement_date, retired_from, terms, contact, tags, origin, arrived_on, flag_reason, flag_until, approver";

    private static final RowMapper<Person> ROW = (rs, n) -> {
        LocalDate stated = rs.getObject("statement_date", LocalDate.class);
        LocalDate retired = rs.getObject("retired_from", LocalDate.class);
        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                null, rs.getLong("version"), rs.getInt("statement_count"),
                rs.getString("stated_total"), stated == null ? null : stated.toString());
        person.setRetiredFrom(retired == null ? null : retired.toString());
        person.setTerms(rs.getObject("terms", Integer.class));
        person.setContact(rs.getString("contact"));
        person.setTags(rs.getString("tags"));
        person.setOrigin(rs.getString("origin"));
        LocalDate arrived = rs.getObject("arrived_on", LocalDate.class);
        person.setArrivedOn(arrived == null ? null : arrived.toString());
        LocalDate flagUntil = rs.getObject("flag_until", LocalDate.class);
        person.setFlag(rs.getString("flag_reason"), flagUntil == null ? null : flagUntil.toString());
        person.setApprover(rs.getString("approver"));
        return person;
    };

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The end of a sheet's list: the place a person added or arriving there takes. */
    private static final String NEXT_POS = "(SELECT COALESCE(MAX(q.list_pos), 0) + 1 FROM person q WHERE q.sheet_id = ?)";

    /** The sheet's people in list order (by their place in it), each with their patrons. */
    public List<Person> list(String sheetId) {
        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY list_pos, id",
                ROW, sheetId);
        Map<Long, Person> byId = new HashMap<>();
        people.forEach((p) -> byId.put(p.getId(), p));
        withGrades(sheetId, people);
        withTerms(sheetId, people);
        withHolds(sheetId, people);
        withAliases(sheetId, people);
        withClashing(sheetId, people);
        withRetirements(sheetId, people);
        withSnapshots(sheetId, people);
        withStatements(sheetId, people);
        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY added_at, patron_id",
                (rs) -> {
                    Person p = byId.get(rs.getLong("person_id"));
                    if (p != null) {
                        p.getPatronIds().add(rs.getLong("patron_id"));
                    }
                }, sheetId);
        return people;
    }

    public Person find(String sheetId, long id) {
        Person person = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
        if (person != null) {
            person.setPatronIds(new ArrayList<>(jdbc.queryForList(
                    "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY added_at, patron_id",
                    Long.class, sheetId, id)));
            withGrades(sheetId, List.of(person));
            withTerms(sheetId, List.of(person));
            withHolds(sheetId, List.of(person));
            withAliases(sheetId, List.of(person));
            withClashing(sheetId, List.of(person));
            withRetirements(sheetId, List.of(person));
            withSnapshots(sheetId, List.of(person));
            withStatements(sheetId, List.of(person));
        }
        return person;
    }

    /** Whether the person was added while the sheet's today was after the date: they were not on
     *  the sheet then (one added before this was kept always was). */
    public boolean addedAfter(String sheetId, long id, LocalDate date) {
        return jdbc.queryForList("SELECT added_on FROM person WHERE sheet_id = ? AND id = ?", LocalDate.class, sheetId, id)
                .stream().anyMatch((on) -> on != null && on.isAfter(date));
    }

    /** The person as they stood at the end of the date, the date standing in for the sheet's today:
     *  the grades, holds and retirement date given them while the sheet's today was on or before it. */
    public Person findAsOf(String sheetId, long id, LocalDate asOf) {
        Person person = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
        if (person == null) {
            return null;
        }
        List<GradeFrom> grades = jdbc.query("SELECT grade, from_date FROM person_grade_history h WHERE h.sheet_id = ? "
                + "AND h.person_id = ? AND h.id = (SELECT MAX(h2.id) FROM person_grade_history h2 WHERE h2.person_id = h.person_id "
                + "AND h2.from_key = h.from_key AND (h2.on_date IS NULL OR h2.on_date <= ?)) ORDER BY from_key",
                (rs, n) -> {
                    LocalDate from = rs.getObject("from_date", LocalDate.class);
                    return new GradeFrom(rs.getString("grade"), from == null ? null : from.toString());
                }, sheetId, id, asOf);
        person.setGrades(new ArrayList<>(grades), asOf);
        withTerms(sheetId, List.of(person));
        person.setHolds(new ArrayList<>(jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? "
                + "AND person_id = ? AND (added_on IS NULL OR added_on <= ?) ORDER BY id", (rs, n) -> {
                    LocalDate to = rs.getObject("to_date", LocalDate.class);
                    return new Hold(rs.getObject("from_date", LocalDate.class).toString(), to == null ? null : to.toString());
                }, sheetId, id, asOf)));
        List<LocalDate> retired = jdbc.queryForList("SELECT retired_from FROM person_retired_history WHERE sheet_id = ? "
                + "AND person_id = ? AND (on_date IS NULL OR on_date <= ?) ORDER BY id DESC LIMIT 1", LocalDate.class,
                sheetId, id, asOf);
        person.setRetiredFrom(retired.isEmpty() || retired.get(0) == null ? null : retired.get(0).toString());
        person.setRetirements(new ArrayList<>(jdbc.query("SELECT from_date, to_date FROM person_retirement WHERE sheet_id = ? "
                + "AND person_id = ? AND to_date <= ? ORDER BY id", (rs, n) -> new Retirement(
                        rs.getObject("from_date", LocalDate.class).toString(), rs.getObject("to_date", LocalDate.class).toString()),
                sheetId, id, asOf)));
        return person;
    }

    /** Give each person their grades, by from-date (none first), and the one in force on the sheet's today. */
    private void withGrades(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        LocalDate today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId)
                .stream().findFirst().orElse(LocalDate.now());
        Map<Long, List<GradeFrom>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, grade, from_date FROM person_grade WHERE sheet_id = ? ORDER BY person_id, from_key",
                (rs) -> {
                    LocalDate from = rs.getObject("from_date", LocalDate.class);
                    grades.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new GradeFrom(rs.getString("grade"), from == null ? null : from.toString()));
                }, sheetId);
        people.forEach((p) -> p.setGrades(grades.getOrDefault(p.getId(), new ArrayList<>()), today));
    }

    /** Give each person their dated terms, by from-date. */
    private void withTerms(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<TermsFrom>> terms = new HashMap<>();
        jdbc.query("SELECT person_id, terms, from_date FROM person_terms WHERE sheet_id = ? ORDER BY person_id, from_date",
                (rs) -> {
                    terms.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new TermsFrom(rs.getObject("terms", Integer.class),
                                    rs.getObject("from_date", LocalDate.class).toString()));
                }, sheetId);
        people.forEach((p) -> p.setDatedTerms(terms.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Give each person their holds, in the order they were added. */
    private void withHolds(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY person_id, id",
                (rs) -> {
                    LocalDate to = rs.getObject("to_date", LocalDate.class);
                    holds.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Hold(rs.getObject("from_date", LocalDate.class).toString(),
                                    to == null ? null : to.toString()));
                }, sheetId);
        people.forEach((p) -> p.setHolds(holds.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Give each person their past retirements, oldest first. */
    private void withRetirements(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<Retirement>> retirements = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_retirement WHERE sheet_id = ? ORDER BY person_id, id",
                (rs) -> {
                    retirements.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Retirement(rs.getObject("from_date", LocalDate.class).toString(),
                                    rs.getObject("to_date", LocalDate.class).toString()));
                }, sheetId);
        people.forEach((p) -> p.setRetirements(retirements.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Give each person the SNAPSHOTs written for them, oldest first. */
    private void withSnapshots(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<Snapshot>> snapshots = new HashMap<>();
        jdbc.query("SELECT person_id, day_left, due_total FROM person_snapshot WHERE sheet_id = ? ORDER BY person_id, id",
                (rs) -> {
                    snapshots.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new Snapshot(rs.getObject("day_left", LocalDate.class).toString(), rs.getString("due_total")));
                }, sheetId);
        people.forEach((p) -> p.setSnapshots(snapshots.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Give each person their statements still standing, oldest first: in the order taken (an as-of
     *  statement goes where it was taken, not where its date falls). */
    private void withStatements(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<StatementLine>> statements = new HashMap<>();
        jdbc.query("SELECT person_id, stated_total, statement_date FROM person_statement WHERE sheet_id = ? "
                + "ORDER BY person_id, taken_at, id",
                (rs) -> {
                    String total = rs.getString("stated_total");
                    statements.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>())
                            .add(new StatementLine(rs.getObject("statement_date", LocalDate.class).toString(),
                                    total == null ? "n/a" : total));
                }, sheetId);
        people.forEach((p) -> p.setStatements(statements.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** Keep a SNAPSHOT written for the person: the day being left and their due-total on it (or n/a). */
    public void addSnapshot(String sheetId, long personId, LocalDate dayLeft, String dueTotal) {
        jdbc.update("INSERT INTO person_snapshot (sheet_id, person_id, day_left, due_total) VALUES (?, ?, ?, ?)",
                sheetId, personId, dayLeft, dueTotal);
    }

    /** Give each person their aliases, sorted as names are compared. */
    private void withAliases(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        Map<Long, List<String>> aliases = new HashMap<>();
        jdbc.query("SELECT person_id, alias FROM person_alias WHERE sheet_id = ? ORDER BY person_id, alias_key, alias, id",
                (rs) -> {
                    aliases.computeIfAbsent(rs.getLong("person_id"), (k) -> new ArrayList<>()).add(rs.getString("alias"));
                }, sheetId);
        people.forEach((p) -> p.setAliases(aliases.getOrDefault(p.getId(), new ArrayList<>())));
    }

    /** The other sheets of the sheet's tree, among the sheets that exist: its ancestors (its parent,
     *  its parent's parent, ...) and its descendants (its children, their children, ...). */
    public java.util.Set<String> treeSheets(String sheetId) {
        java.util.Set<String> tree = new java.util.LinkedHashSet<>();
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
            tree.add(at);
        }
        List<String> below = new ArrayList<>(List.of(sheetId));
        java.util.Set<String> seenBelow = new java.util.HashSet<>(List.of(sheetId));
        for (int i = 0; i < below.size(); i++) {
            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting = 'parent' AND val = ?",
                    String.class, below.get(i))) {
                if (seenBelow.add(child)) {
                    below.add(child);
                    tree.add(child);
                }
            }
        }
        tree.remove(sheetId);
        tree.removeIf((s) -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) == 0);
        return tree;
    }

    /** The sheet's descendants (its children, their children, ...) among the sheets that exist, by id. */
    public List<String> descendantSheets(String sheetId) {
        List<String> below = new ArrayList<>(List.of(sheetId));
        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
        for (int i = 0; i < below.size(); i++) {
            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting = 'parent' AND val = ?",
                    String.class, below.get(i))) {
                if (seen.add(child)) below.add(child);
            }
        }
        below.remove(0);
        below.removeIf((s) -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) == 0);
        below.sort(null);
        return below;
    }

    private String parentOf(String sheetId) {
        return jdbc.queryForList("SELECT val FROM sheet_setting WHERE sheet_id = ? AND setting = 'parent'",
                String.class, sheetId).stream().filter((v) -> v != null && !v.isBlank()).findFirst().orElse(null);
    }

    /** The names and aliases used on the other sheets of the sheet's tree, as names are compared
     *  (lower-cased, trimmed). */
    public java.util.Set<String> treeNames(String sheetId) {
        java.util.Set<String> names = new java.util.HashSet<>();
        for (String other : treeSheets(sheetId)) {
            names.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet_id = ?", String.class, other));
            names.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet_id = ?", String.class, other));
        }
        return names;
    }

    /** Whether the name is used, as a name or alias, on another sheet of the sheet's tree. */
    public boolean nameTakenInTree(String sheetId, String name) {
        return treeNames(sheetId).contains(key(name));
    }

    private static String key(String name) {
        return name == null ? "" : name.trim().toLowerCase(java.util.Locale.ROOT);
    }

    /** Mark each person whose name or an alias is used on another sheet of the sheet's tree. */
    private void withClashing(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return;
        }
        java.util.Set<String> names = treeNames(sheetId);
        people.forEach((p) -> p.setClashing(names.contains(key(p.getName()))
                || p.getAliases().stream().anyMatch((a) -> names.contains(key(a)))));
    }

    /** Give the person the alias (stored as given, trimmed). */
    public void addAlias(Person person, String alias, String user) {
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_by) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), alias, user);
        person.getAliases().add(alias);
        person.getAliases().sort(String.CASE_INSENSITIVE_ORDER);
    }

    /** Name the patron as one of the person's patrons. */
    public void addPatron(Person person, Person patron, String user) {
        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), patron.getId(), user);
        person.getPatronIds().add(patron.getId());
    }

    /** The person on the sheet with this name or alias, compared ignoring case and surrounding spaces; null when none. */
    public Person findByName(String sheetId, String name) {
        Person found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND (name_key = LOWER(TRIM(?)) "
                + "OR id IN (SELECT person_id FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?))))",
                ROW, sheetId, name, sheetId, name).stream().findFirst().orElse(null);
        return found == null ? null : find(sheetId, found.getId());
    }

    /** Whether another person on the sheet (not {@code exceptId}) already has this name, or anyone
     *  on the sheet has it as an alias, compared ignoring case and surrounding spaces. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT (SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND (? IS NULL OR id <> ?)) "
                        + "+ (SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND alias_key = LOWER(TRIM(?)))",
                Integer.class, sheetId, name, exceptId, exceptId, sheetId, name);
        return n != null && n > 0;
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this contact. */
    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND (? IS NULL OR id <> ?)",
                Integer.class, sheetId, contact, exceptId, exceptId);
        return n != null && n > 0;
    }

    public Person add(String sheetId, String name, String grade, String user) {
        return add(sheetId, name, grade, null, null, null, user);
    }

    /** Add a person with their grade (from the beginning of time), own terms (null: none) and
     *  contact (null: none). */
    public Person add(String sheetId, String name, String grade, Integer terms, String contact, String user) {
        return add(sheetId, name, grade, terms, contact, null, user);
    }

    /** Add a person as above, with their tags (null: none; see {@link net.officefloor.hq.app.claim.ClaimForm#tags}). */
    public Person add(String sheetId, String name, String grade, Integer terms, String contact, String tags, String user) {
        GeneratedKeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, created_by, terms, contact, tags, added_on, list_pos) "
                            + "VALUES (?, ?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), " + NEXT_POS + ")",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setString(3, user);
            ps.setObject(4, terms);
            ps.setString(5, contact);
            ps.setString(6, tags);
            ps.setString(7, sheetId);
            ps.setString(8, sheetId);
            return ps;
        }, key);
        long id = key.getKey().longValue();
        // The first grade a person is given applies from the beginning of time.
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by) VALUES (?, ?, ?, NULL, ?)",
                sheetId, id, grade, user);
        gradeHistory(sheetId, id, grade, null);
        Person person = new Person(id, sheetId, name, grade, 0);
        person.getGrades().add(new GradeFrom(grade, null));
        person.setTerms(terms);
        person.setContact(contact);
        person.setTags(tags);
        useTags(sheetId, tags);
        return person;
    }

    /** Record the grade the person was just given (see {@link Person#giveGrade}), replacing the one
     *  with the same from-date. */
    public void saveGrade(Person person, GradeFrom given, String user) {
        LocalDate from = given.from() == null ? null : LocalDate.parse(given.from());
        if (from == null) {
            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NULL",
                    person.getSheetId(), person.getId());
        } else {
            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date = ?",
                    person.getSheetId(), person.getId(), from);
        }
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by) VALUES (?, ?, ?, ?, ?)",
                person.getSheetId(), person.getId(), given.grade(), from, user);
        gradeHistory(person.getSheetId(), person.getId(), given.grade(), from);
    }

    /** Record the dated terms the person was just given (see {@link Person#giveTermsFrom}), replacing
     *  those with the same from-date. */
    public void saveTerms(Person person, TermsFrom given, String user) {
        LocalDate from = LocalDate.parse(given.from());
        jdbc.update("DELETE FROM person_terms WHERE sheet_id = ? AND person_id = ? AND from_date = ?",
                person.getSheetId(), person.getId(), from);
        jdbc.update("INSERT INTO person_terms (sheet_id, person_id, terms, from_date, set_by) VALUES (?, ?, ?, ?, ?)",
                person.getSheetId(), person.getId(), given.terms(), from, user);
    }

    /** Keep a grade given in the person's history, with the sheet's today. */
    private void gradeHistory(String sheetId, long personId, String grade, LocalDate from) {
        jdbc.update("INSERT INTO person_grade_history (sheet_id, person_id, grade, from_date, on_date) "
                + "VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", sheetId, personId, grade, from, sheetId);
    }

    /** Save the person over the version it was loaded at, raising the version; false (nothing
     *  written) when someone else has saved the person since. */
    public boolean update(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, terms = ?, contact = ?, tags = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getBaseTerms(), person.getContact(), person.getTags(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 0) {
            return false;
        }
        person.setVersion(person.getVersion() + 1);
        useTags(person.getSheetId(), person.getTags());
        return true;
    }

    /** Keep each of the tags (comma separated; null: none) among those ever used on the sheet. */
    private void useTags(String sheetId, String tags) {
        if (tags == null) return;
        for (String tag : tags.split(",")) {
            jdbc.update("MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", sheetId, tag);
        }
    }

    /** Save the statement just taken of the person (not an edit: the version stays). */
    public void updateStatements(Person person) {
        saveStatements(person);
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), person.getStatedTotal(), LocalDate.parse(person.getStatementDate()));
    }

    /** Drop the person's last statement kept, and load the one before it into the person (none: they
     *  show no statement); their count goes down by one (not an edit: the version stays). */
    public void cancelStatement(Person person) {
        List<Long> kept = jdbc.queryForList(
                "SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC LIMIT 2",
                Long.class, person.getSheetId(), person.getId());
        if (!kept.isEmpty()) {
            jdbc.update("DELETE FROM person_statement WHERE id = ?", kept.get(0));
        }
        String[] before = kept.size() < 2 ? null : jdbc.queryForObject(
                "SELECT stated_total, statement_date FROM person_statement WHERE id = ?",
                (rs, n) -> new String[] { rs.getString("stated_total"),
                        rs.getObject("statement_date", LocalDate.class).toString() }, kept.get(1));
        person.unstated(before == null ? null : before[0], before == null ? null : before[1]);
        saveStatements(person);
    }

    private void saveStatements(Person person) {
        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE sheet_id = ? AND id = ?",
                person.getStatementCount(), person.getStatedTotal(),
                person.getStatementDate() == null ? null : LocalDate.parse(person.getStatementDate()),
                person.getSheetId(), person.getId());
    }

    /** Save the person's retirement date (not an edit: the version stays). */
    public void updateRetired(Person person) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?",
                LocalDate.parse(person.getRetiredFrom()), person.getSheetId(), person.getId());
        jdbc.update("INSERT INTO person_retired_history (sheet_id, person_id, retired_from, on_date) "
                + "VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", person.getSheetId(), person.getId(),
                LocalDate.parse(person.getRetiredFrom()), person.getSheetId());
    }

    /** Save the person's unretirement (not an edit: the version stays): not retired, their last past
