245	     *  its parent's parent, ...) and its descendants (its children, their children, ...). */
246	    public java.util.Set<String> treeSheets(String sheetId) {
247	        java.util.Set<String> tree = new java.util.LinkedHashSet<>();
248	        java.util.Set<String> seen = new java.util.HashSet<>(List.of(sheetId));
249	        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
250	            tree.add(at);
251	        }
252	        List<String> below = new ArrayList<>(List.of(sheetId));
253	        java.util.Set<String> seenBelow = new java.util.HashSet<>(List.of(sheetId));
254	        for (int i = 0; i < below.size(); i++) {
255	            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting = 'parent' AND val = ?",
256	                    String.class, below.get(i))) {
257	                if (seenBelow.add(child)) {
258	                    below.add(child);
259	                    tree.add(child);
260	                }
261	            }
262	        }
263	        tree.remove(sheetId);
264	        tree.removeIf((s) -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) == 0);
265	        return tree;
266	    }
