529	    /** Merge the person {@code from} into {@code into}: from's name and aliases become into's aliases;
530	     *  from's patrons are added to into's (not into themselves, no repeats); anyone naming from as
531	     *  patron names into instead (no repeats); into's statement count becomes theirs plus from's, their
532	     *  last statement staying theirs (having none, becoming from's), from's statements kept before
533	     *  into's; from's holds, watchers, grades and the person themselves are dropped; from's plans and crews become into's. Their claims, pool memberships and period totals must have
534	     *  moved first. */
535	    public void merge(Person from, Person into, String user) {
536	        String sheetId = into.getSheetId();
537	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_by) VALUES (?, ?, ?, ?)",
538	                sheetId, into.getId(), from.getName(), user);
539	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
540	                into.getId(), sheetId, from.getId());
541	        for (Long patronId : from.getPatronIds()) {
542	            if (patronId != into.getId() && !into.getPatronIds().contains(patronId)) {
543	                jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
544	                        sheetId, into.getId(), patronId, user);
545	                into.getPatronIds().add(patronId);
546	            }
547	        }
548	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
549	        // Whoever named from names into instead, unless that is into themselves or they name into already.
550	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ? OR person_id IN "
551	                + "(SELECT k.person_id FROM person_patron k WHERE k.sheet_id = ? AND k.patron_id = ?))",
552	                sheetId, from.getId(), into.getId(), sheetId, into.getId());
553	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
554	                into.getId(), sheetId, from.getId());
555	        into.getPatronIds().remove(Long.valueOf(from.getId()));
556	        // from's statements go before into's, so into's last stays their last.
557	        List<Long> own = jdbc.queryForList("SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? ORDER BY id",
558	                Long.class, sheetId, into.getId());
559	        jdbc.update("UPDATE person_statement SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
560	                into.getId(), sheetId, from.getId());
561	        for (Long id : own) {
562	            jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date, taken_at) "
563	                    + "SELECT sheet_id, person_id, stated_total, statement_date, taken_at FROM person_statement WHERE id = ?", id);
564	            jdbc.update("DELETE FROM person_statement WHERE id = ?", id);
565	        }
566	        into.absorbStatements(from);
567	        saveStatements(into);
568	        for (String table : List.of("person_hold", "person_watch", "person_grade", "person_terms",
569	                "person_grade_history", "person_retired_history", "person_retirement")) {
570	            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
571	        }
572	        // from's plans go on making claims, now for into.
573	        jdbc.update("UPDATE plan SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
574	        // from's crews become into's: crews from leads into leads; from's memberships move to into, unless
575	        // into is in that crew already or leads it.
576	        jdbc.update("UPDATE crew SET lead_id = ? WHERE sheet_id = ? AND lead_id = ?", into.getId(), sheetId, from.getId());
577	        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
578	                + "(SELECT m.crew_id FROM crew_member m WHERE m.person_id = ?)", sheetId, from.getId(), into.getId());
579	        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", into.getId(), sheetId, from.getId());
580	        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_id IN "
581	                + "(SELECT c.id FROM crew c WHERE c.lead_id = ?)", sheetId, into.getId(), into.getId());
582	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.getId());
583	        withAliases(sheetId, List.of(into));
584	    }
