586	    /** Move the person to the sheet {@code to} with their grades (and grade history) and aliases, their
587	     *  statements dropped (the count back to 0) and their plans going with them; their holds, watchers, patron links (either way), pool
588	     *  and crew memberships and closed periods' fixed totals are dropped (crews they lead stay, without a lead); they keep the sheet they came from as their
589	     *  origin. When {@code merging} (they are to be merged into someone there straight after) they keep
590	     *  their statements and arrive under a stand-in name, as theirs is taken there. Their claims must
591	     *  have moved first. They are marked as arriving on {@code arrivedOn}, the sheet {@code to}'s today. */
592	    public void transfer(Person person, String to, boolean merging, LocalDate arrivedOn) {
593	        String sheetId = person.getSheetId();
594	        long id = person.getId();
595	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", sheetId, id, id);
596	        for (String table : List.of("person_hold", "person_watch", "pool_member", "crew_member")) {
597	            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, id);
598	        }
599	        // A crew they lead stays, without a lead.
600	        jdbc.update("UPDATE crew SET lead_id = NULL WHERE sheet_id = ? AND lead_id = ?", sheetId, id);
601	        // Statements kept from leaving any sheet but the one they go to (an undo gives those back) go.
602	        for (String table : List.of("person_left", "person_statement_left")) {
603	            jdbc.update("DELETE FROM " + table + " WHERE person_id = ? AND (sheet_id <> ? OR ?)", id, to, merging);
604	        }
605	        if (merging) {
606	            jdbc.update("UPDATE person_statement SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
607	        } else {
608	            jdbc.update("INSERT INTO person_left (sheet_id, person_id, statement_count, stated_total, statement_date) "
609	                    + "SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person WHERE sheet_id = ? AND id = ?", sheetId, id);
610	            jdbc.update("INSERT INTO person_statement_left (sheet_id, person_id, stated_total, statement_date, taken_at) "
611	                    + "SELECT sheet_id, person_id, stated_total, statement_date, taken_at FROM person_statement "
612	                    + "WHERE sheet_id = ? AND person_id = ? ORDER BY id", sheetId, id);
613	            jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, id);
614	            jdbc.update("UPDATE person SET statement_count = 0, stated_total = NULL, statement_date = NULL "
615	                    + "WHERE sheet_id = ? AND id = ?", sheetId, id);
616	        }
617	        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", id);
618	        jdbc.update("DELETE FROM period_opening WHERE person_id = ?", id);
619	        for (String table : List.of("person_grade", "person_terms", "person_grade_history", "person_retired_history", "person_retirement", "person_alias", "plan")) {
620	            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, sheetId, id);
621	        }
622	        String name = merging ? "#merging-" + id : person.getName();
623	        jdbc.update("UPDATE person SET sheet_id = ?, name = ?, "
624	                + "origin = ?, arrived_on = ?, list_pos = " + NEXT_POS + " WHERE sheet_id = ? AND id = ?",
625	                to, name, sheetId, arrivedOn, to, sheetId, id);
626	    }
