    22	 *  due by a day in a closed period, one not OPEN or deferred, a role that may not open a claim, and an amount that is
    23	 *  not more than 0.00 and less than the claim's (two decimals at most). */
    24	public class SplitClaim {
    25	    public void split(@RequestParam(name = "by", required = false) String by,
    26	            @RequestParam(name = "amount", required = false) String amount, @Val Claim claim,
    27	            ClaimRepository claims, PeriodRepository periods, SettingRepository settings,
    28	            SheetRepository sheets, RoleRepository roles, PersonRepository people, HolidayRepository holidays,
    29	            Out<Split> split)
    30	            throws ClaimStatusException, InvalidClaimException, PeriodClosedException {
    31	        String sheetId = claim.getSheetId();
