    34	            throw new ClaimStatusException("A " + (claim.isDeferred() ? "deferred" : claim.getStatus())
    35	                    + " claim cannot be split");
    36	        }
    37	        if (!Permissions.allows(sheetId, by, Permissions.OPEN, roles, settings)) {
    38	            throw new ClaimStatusException("Your role may not open a claim");
    39	        }
    40	        BigDecimal part;
    41	        try {
    42	            part = new BigDecimal(amount == null ? "" : amount.trim());
    43	        } catch (NumberFormatException e) {
    44	            throw new InvalidClaimException("Not an amount: " + amount);
    45	        }
    46	        BigDecimal whole = new BigDecimal(claim.getAmount());
    47	        if (part.scale() > 2 || part.signum() <= 0 || part.compareTo(whole) >= 0) {
    48	            throw new InvalidClaimException("A split needs an amount more than 0.00 and less than " + claim.getAmount());
    49	        }
    50	        claim.setAmount(whole.subtract(part).setScale(2).toPlainString());
    51	        claim.bind(false, null);
    52	
    53	        String user = by == null ? "" : by;
    54	        LocalDate date = LocalDate.parse(claim.getDate());
    55	        Person person = people.find(sheetId, claim.getPersonId());
    56	        LocalDate dueBy = holidays.dueBy(sheetId, date, settings.termsToday(sheetId, person));
    57	        Claim created = claims.add(sheetId, claim.getPersonId(), part.setScale(2), date, claim.getNote(),
    58	                null, dueBy, user, null, claim.getTags());
    59	        if (periods.softClosedOn(sheetId, created.getDueBy())) claims.markLateEntry(created);
    60	        created.setStatus(ClaimStatus.OPEN.name());
    61	        created.setNumber(ClaimNumbers.next(created, claims, periods, settings, sheets));
