    20	     *  (the one being edited) out of the corrections already made. */
    21	    public static String check(ValidClaim request, String sheetId, long personId, ClaimRepository claims,
    22	            long exceptId) throws InvalidClaimException {
    23	        if (!request.isCorrection()) return null;
    24	        Claim corrected = claims.findByNumber(sheetId, request.corrects());
    25	        if (corrected == null || corrected.getPersonId() != personId
    26	                || !ClaimStatus.SETTLED.name().equals(corrected.getStatus())) {
    27	            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person");
    28	        }
    29	        BigDecimal remains = new BigDecimal(corrected.getAmount());
    30	        for (Claim c : claims.listOf(sheetId, personId)) {
    31	            if (c.getId() == exceptId || !request.corrects().equals(c.getCorrects())
    32	                    || ClaimStatus.VOID.name().equals(c.getStatus())
    33	                    || ClaimStatus.DELETED.name().equals(c.getStatus())) continue;
    34	            remains = remains.add(new BigDecimal(c.getAmount()));
    35	        }
    36	        if (request.amount().negate().compareTo(remains) > 0) {
    37	            throw new InvalidClaimException("A correction may not exceed what remains of the claim: "
    38	                    + remains.setScale(2).toPlainString());
    39	        }
    40	        return request.corrects();
    41	    }
