    21	/** How a period is closed: shared by a close by hand ({@link ClosePeriod}) and the auto close of a
    22	 *  today change ({@link AutoClosePeriods}). */
    23	public final class PeriodClosing {
    24	    private PeriodClosing() {
    25	    }
    26	
    27	    /** Close the open period now, as a close by hand does (no permission check): used by the
    28	     *  sheet's today change to close the periods past their grace days. */
    29	    public static Period closeNow(Period found, String user, PeriodRepository periods, ClaimRepository claims,
    30	            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
    31	            SheetRepository sheets) {
    32	        return fixNow(found, user, false, periods, claims, log, people, rates, settings, sheets);
    33	    }
    34	
    35	    /** Close or (soft) soft-close the period now, fixing its figures (and everyone's carried figure) as they are now (no permission check). */
    36	    public static Period fixNow(Period found, String user, boolean soft, PeriodRepository periods, ClaimRepository claims,
    37	            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
    38	            SheetRepository sheets) {
    39	        String id = found.sheetId();
    40	        DatedSetting floor = settings.floor(id);
    41	        Dues.Late late = settings.late(id, sheets.today(id));
    42	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    43	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
    44	        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
    45	        for (Person p : people.list(id)) {
    46	            personTotals.put(p.getId(), BigDecimal.ZERO.setScale(2));
    47	            personCarried.put(p.getId(), BigDecimal.ZERO.setScale(2));
    48	        }
    49	        List<Period> earlier = periods.list(id).stream().filter((e) -> e.to().compareTo(found.from()) < 0).toList();
    50	        Map<Long, String> atEnd = log.statusesOn(id, LocalDate.parse(found.to()));
    51	        for (Claim c : claims.list(id)) {
    52	            boolean in = found.contains(c.getDueBy());
    53	            // Carried: due by a day in an earlier period, still OPEN or PENDING at the end of this one.
    54	            boolean carried = !in && earlier.stream().anyMatch((e) -> e.contains(c.getDueBy()));
    55	            if (!in && !carried) continue;
    56	            String status = atEnd.containsKey(c.getId()) ? atEnd.get(c.getId()) : c.getStatus();
    57	            if (status == null || !(ClaimStatus.isOpen(status) || (in && ClaimStatus.SETTLED.name().equals(status)))) continue;
    58	            Person person = people.find(id, c.getPersonId());
    59	            if (person != null && person.leftOutLive(c)) continue;
    60	            Rate rate = person == null ? null
    61	                    : rates.find(id, person.gradeOn(c.getDate()), LocalDate.parse(c.getDate()), c.getId());
    62	            String due = Dues.shown(c, rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
    63	            if (due == null) continue;
    64	            if (carried) {
    65	                if (person != null) personCarried.merge(person.getId(), new BigDecimal(due), BigDecimal::add);
    66	                continue;
    67	            }
    68	            total = total.add(new BigDecimal(due));
    69	            if (person != null) personTotals.merge(person.getId(), new BigDecimal(due), BigDecimal::add);
    70	        }
    71	        // An opening balance is part of the carried figure fixed now.
    72	        found.personOpenings().forEach((pid, amount) -> {
    73	            if (personCarried.containsKey(pid)) personCarried.merge(pid, new BigDecimal(amount), BigDecimal::add);
    74	        });
    75	        return periods.close(found, total, personTotals, personCarried, user, soft);
    76	    }
    77	}
