    24	 *  sheet's claimed-total, due-total and overdue-total (these two leave out the single highest and
    25	 *  lowest person's figure when three or more people have one), with the sheet's alert threshold
    26	 *  (null: off). */
    27	public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal,
    28	        BigDecimal alertThreshold) {
    29	
    30	    /** A person's figures: their name, claimed, due-total (null: n/a) and overdue-total (the shown
    31	     *  dues of their open claims past their due-by plus grace days on the sheet's today, n/a ones skipped). */
    32	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
    33	        public boolean sameAs(Figures other) {
    34	            return other != null && claimed.equals(other.claimed)
    35	                    && (dueTotal == null ? other.dueTotal == null : dueTotal.equals(other.dueTotal))
    36	                    && overdueTotal.equals(other.overdueTotal);
    37	        }
    38	    }
