    40	    /** The sheet's figures now. */
    41	    public static Rollup of(String sheetId, PersonRepository people, ClaimRepository claims,
    42	            RateRepository rates, SheetRepository sheets, SettingRepository settings) {
    43	        List<Rate> sheetRates = rates.list(sheetId);
    44	        DatedSetting floor = settings.floor(sheetId);
    45	        BigDecimal cap = settings.cap(sheetId);
    46	        LocalDate todayDate = sheets.today(sheetId);
    47	        String today = todayDate.toString();
    48	        Dues.Late late = settings.late(sheetId, todayDate);
    49	        List<Claim> all = claims.list(sheetId);
    50	        Map<Long, Figures> figures = new LinkedHashMap<>();
    51	        BigDecimal claimedTotal = zero();
    52	        List<BigDecimal> dues = new ArrayList<>();
    53	        List<BigDecimal> overdues = new ArrayList<>();
    54	        for (Person p : people.list(sheetId)) {
    55	            BigDecimal claimed = zero();
    56	            BigDecimal due = zero();
    57	            BigDecimal overdue = zero();
    58	            boolean kept = false;
    59	            for (Claim c : all) {
    60	                if (c.getPersonId() != p.getId()) continue;
    61	                if (!corrects(c) && p.countsClaimed(c)) claimed = claimed.add(new BigDecimal(c.getAmount()));
    62	                if (!p.countsLive(c)) continue;
    63	                String grade = p.gradeOn(c.getDate());
    64	                Rate rate = RateRepository.inForce(sheetRates, grade, c.getDate(), c.getId());
    65	                String pct = rate == null ? null : rate.pct();
    66	                String d = Dues.shown(c, pct == null ? null : Dues.of(c.getAmount(), pct, late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
    67	                kept |= c.getSettledDue() != null || c.isBound()
    68	                        || (pct != null && (!grade.equals(p.getGrade()) || c.getDate().compareTo(today) <= 0));
    69	                if (d != null) due = due.add(new BigDecimal(d));
    70	                if (d != null && ClaimStatus.isOpen(c.getStatus()) && late.lateFrom(c).isBefore(todayDate)) {
    71	                    overdue = overdue.add(new BigDecimal(d));
    72	                }
    73	            }
    74	            boolean na = rateOn(sheetRates, p.getGrade(), today) == null && !kept;
    75	            if (cap != null && due.compareTo(cap) > 0) due = cap.setScale(2);
    76	            figures.put(p.getId(), new Figures(p.getName(), claimed.toPlainString(),
    77	                    na ? null : due.toPlainString(), overdue.toPlainString()));
    78	            claimedTotal = claimedTotal.add(claimed);
    79	            if (!na) dues.add(due);
    80	            overdues.add(overdue);
    81	        }
    82	        return new Rollup(figures, claimedTotal.toPlainString(), trimmedSum(dues).toPlainString(),
    83	                trimmedSum(overdues).toPlainString(), settings.alertThreshold(sheetId));
    84	    }
