    86	    /** The audit lines after a change from {@code before} to this: one ROLLUP per person whose
    87	     *  figures moved (a new person counts as moved), then TOTALS when a sheet total moved, then an
    88	     *  ALERT per person (in list order) whose due-total went from at or below the alert threshold
    89	     *  (or none) to above it. */
    90	    public List<String> changesSince(Rollup before, String sheetId, String by) {
    91	        String head = " sheet=" + sheetId + " by=" + by;
    92	        List<String> lines = new ArrayList<>();
    93	        people.forEach((id, now) -> {
    94	            if (!now.sameAs(before.people.get(id))) {
    95	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
    96	                        + " due-total=" + (now.dueTotal() == null ? "n/a" : now.dueTotal())
    97	                        + " overdue-total=" + now.overdueTotal());
    98	            }
    99	        });
   100	        if (!claimedTotal.equals(before.claimedTotal) || !dueTotal.equals(before.dueTotal)
   101	                || !overdueTotal.equals(before.overdueTotal)) {
   102	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
   103	                    + " overdue-total=" + overdueTotal);
   104	        }
   105	        if (alertThreshold != null) {
   106	            people.forEach((id, now) -> {
   107	                Figures was = before.people.get(id);
   108	                if (above(now) && (was == null || !above(was))) {
   109	                    lines.add("ALERT" + head + " name=" + now.name() + " due-total=" + now.dueTotal());
   110	                }
   111	            });
   112	        }
   113	        return lines;
   114	    }
   115	
   116	    /** Whether the person's due-total is above the alert threshold (none: not). */
   117	    private boolean above(Figures figures) {
   118	        return figures.dueTotal() != null && new BigDecimal(figures.dueTotal()).compareTo(alertThreshold) > 0;
   119	    }
   120	
   121	    /** Whether the claim corrects another: such a claim is left out of claimed. */
   122	    private static boolean corrects(Claim c) {
   123	        return c.getCorrects() != null && !c.getCorrects().isBlank();
   124	    }
   125	
   126	    /** The grade's rate in force on the date (yyyy-MM-dd), inherited up the parent chain; null when none. */
   127	    private static String rateOn(List<Rate> rates, String grade, String date) {
   128	        Rate found = RateRepository.inForce(rates, grade, date);
   129	        return found == null ? null : found.pct();
   130	    }
   131	
   132	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
   133	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
   134	        List<BigDecimal> sorted = new ArrayList<>(figures);
   135	        sorted.sort(BigDecimal::compareTo);
   136	        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
   137	        BigDecimal total = zero();
   138	        for (BigDecimal f : sorted) total = total.add(f);
   139	        return total;
   140	    }
   141	
   142	    private static BigDecimal zero() {
   143	        return BigDecimal.ZERO.setScale(2);
   144	    }
   145	}
