    84	            // counted in business days past the weekends and the sheet's holidays as they are now.
    85	            LocalDate dueBy = holidays.dueBy(id, date, settings.termsToday(id, person));
    86	            periods.requireOpen(id, dueBy.toString());
    87	            String corrects = Corrections.check(request, id, person.getId(), claims);
