    89	            claims.requireRefFree(id, request.ref(), 0);
    90	            if (request.ref() != null && !refs.add(request.ref().toLowerCase(Locale.ROOT))) {
    91	                throw new InvalidClaimException("The reference is repeated in the paste: " + request.ref());
    92	            }
