    94	        }
    95	
    96	        List<String> records = new ArrayList<>();
    97	        Rollup before = Rollup.of(id, people, claims, rates, sheets, settings);
    98	        for (Pending p : pending) {
    99	            String head = " sheet=" + id + " by=" + user + " person=" + p.person().getName();
   100	            Claim claim;
   101	            if (p.match() != null) {
   102	                claim = claims.find(id, p.match().getId());
   103	                // An earlier line of the paste may have opened it already.
   104	                if (!ClaimStatus.DRAFT.name().equals(claim.getStatus())) {
   105	                    throw new InvalidClaimException("No DRAFT claim of " + p.person().getName() + " matches the line");
   106	                }
