   136	            // Opened as the open button opens it.
   137	            OpenChecks.requireFlagSteward(claim, user, people, roles);
   138	            periods.requireOpen(id, claim.getDueBy());
   139	            ClaimStatus opened = OpenChecks.opensTo(claim, people, rates, settings, sheets);
   140	            OpenChecks.requireNote(claim, people, rates, settings, sheets);
   141	            OpenChecks.requireUnderCap(claim, claims, periods);
   142	            claim.setStatus(opened.name());
   143	            if (opened == ClaimStatus.OPEN) {
   144	                claim.setNumber(ClaimNumbers.next(claim, claims, periods, settings, sheets));
   145	            }
   146	            claim.setOpenedBy(user);
   147	            claims.update(claim);
   148	            log.record(claim, user);
   149	            records.add(opened.event() + head + " amount=" + claim.getAmount() + " date=" + claim.getDate()
   150	                    + claim.getAuditNumber());
