   152	            records.addAll(after.changesSince(before, id, user));
   153	            before = after;
   154	        }
   155	        // Every line went through: only now is anything recorded.
   156	        for (String record : records) {
   157	            audit.record(record);
   158	        }
   159	        result.set(new PasteResult(pending.size()));
