   162	    /** The newest DRAFT of the person's claims (newest first) on the date with the note (blank: none);
   163	     *  null when none of them matches; refused when they match only claims that are not DRAFT. */
   164	    private static Claim match(List<Claim> theirs, LocalDate date, String note) throws InvalidClaimException {
   165	        String wanted = note == null ? "" : note.trim();
   166	        boolean matched = false;
   167	        for (Claim c : theirs) {
   168	            if (ClaimStatus.VOID.name().equals(c.getStatus()) || ClaimStatus.DELETED.name().equals(c.getStatus())) {
   169	                continue;
   170	            }
   171	            String has = c.getNote() == null ? "" : c.getNote().trim();
   172	            if (!date.toString().equals(c.getDate()) || !wanted.equals(has)) continue;
   173	            if (ClaimStatus.DRAFT.name().equals(c.getStatus())) return c;
   174	            matched = true;
   175	        }
   176	        if (matched) {
   177	            throw new InvalidClaimException("The line matches a claim that is no longer a DRAFT");
   178	        }
   179	        return null;
   180	    }
   181	}
