    12	/** Splits the paste into its lines (blank lines skipped; a note ending in
    13	 *  " #<reference>" gives the claim that reference) and checks each with the claim form's own
    14	 *  rules; a paste with no lines, or a line without a name, is refused. */
    15	public class ValidatePaste {
    16	    public void validate(@RequestBody PasteRequest request, Out<PasteLines> lines)
    17	            throws InvalidClaimException {
    18	        String text = request == null || request.text() == null ? "" : request.text();
    19	        List<PasteLine> checked = new ArrayList<>();
    20	        for (String line : text.split("\\r?\\n")) {
    21	            if (line.isBlank()) continue;
    22	            String[] f = line.split(",", 4);
    23	            String name = f[0].trim();
    24	            if (name.isEmpty()) {
    25	                throw new InvalidClaimException("Each line needs a name: " + line);
    26	            }
    27	            // A note ending in " #<reference>" gives the claim's reference: that part is not the note.
    28	            String note = f.length > 3 ? f[3].trim() : "";
    29	            String ref = "";
    30	            int hash = note.lastIndexOf(" #");
    31	            if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
    32	                ref = note.substring(hash + 2);
    33	                note = note.substring(0, hash);
    34	            }
    35	            ValidClaim claim = ClaimForm.check(new ClaimRequest(f.length > 1 ? f[1] : "",
    36	                    f.length > 2 ? f[2] : "", note, null, ref));
    37	            checked.add(new PasteLine(name, claim));
    38	        }
    39	        if (checked.isEmpty()) {
    40	            throw new InvalidClaimException("Paste at least one line of name,amount,date,note");
    41	        }
    42	        lines.set(new PasteLines(checked));
    43	    }
    44	}

