404	   222	     *  force on the sheet's today ({@code held}); the others' cut is 0.00, but a member whose dates do not
405	   223	     *  include the sheet's today is left out entirely (cut ""), as is every member when each current member
406	   224	     *  is retired (the pool shows no cuts). Each member with a cut gets the pot
407	   225	     *  times their share over the shares of the members with a cut added up, rounded half to even to two
408	   226	     *  decimals; the remainder goes to the member with the smallest non-zero cut (the latest added on a tie; a
409	   227	     *  member with no cut gets none), or to the last member with a cut and a share when no cut is non-zero, so the cuts total exactly the pot (all 0.00 when no member has a cut). */
410	   228	    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
411	   229	        if (members.stream().anyMatch(PoolMember::current)
412	   230	                && members.stream().filter(PoolMember::current).allMatch(PoolMember::retired)) {
413	   231	            return members.stream().map(m -> m.withCut("")).toList();
414	   232	        }
415	   233	        BigDecimal[] cuts = new BigDecimal[members.size()];
416	   234	        boolean[] cutting = new boolean[members.size()];
417	   235	        BigDecimal shares = BigDecimal.ZERO.setScale(2);
418	   236	        for (int i = 0; i < members.size(); i++) {
419	   237	            PoolMember m = members.get(i);
420	   238	            cutting[i] = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
