422	   240	        }
423	   241	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
424	   242	        int smallest = -1;
425	   243	        int last = -1;
426	   244	        for (int i = 0; i < members.size(); i++) {
427	   245	            BigDecimal share = new BigDecimal(members.get(i).share());
428	   246	            cuts[i] = cutting[i] ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
429	   247	                    : BigDecimal.ZERO.setScale(2);
430	   248	            sum = sum.add(cuts[i]);
431	   249	            if (cutting[i] && share.signum() != 0) last = i;
432	   250	            if (cutting[i] && cuts[i].signum() != 0
433	   251	                    && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
434	   252	                smallest = i;
435	   253	            }
436	   254	        }
437	   255	        int to = smallest >= 0 ? smallest : last;
