439	   257	        List<PoolMember> cut = new ArrayList<>();
440	   258	        for (int i = 0; i < members.size(); i++) {
441	   259	            cut.add(members.get(i).withCut(members.get(i).current() ? cuts[i].toPlainString() : ""));
442	   260	        }
443	   261	        return cut;
444	   262	    }
