    22	/** Preview a candidate rate for a grade on every date: the open (OPEN or PENDING) claims of people on
    23	 *  that grade on the claim's date whose shown due would differ, and the sum of the differences. A claim
    24	 *  bound by a statement keeps its figure; a settled one is not open. Reads only: nothing is written. */
    25	public class PreviewRate {
    26	    public void preview(@PathVariable("sheetId") String sheetId, @Val ValidRate candidate,
    27	            ClaimRepository claims, PersonRepository people, RateRepository rates, SheetRepository sheets,
    28	            SettingRepository settings, ObjectResponse<RatePreview> response) {
    29	        String id = sheetId.trim();
    30	        List<Rate> sheetRates = rates.list(id);
    31	        Map<Long, Person> byId = people.list(id).stream().collect(Collectors.toMap(Person::getId, Function.identity()));
    32	        DatedSetting floor = settings.floor(id);
    33	        Dues.Late late = settings.late(id, sheets.today(id));
    34	        String pct = candidate.pct().toPlainString();
    35	        int count = 0;
    36	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
    37	        for (Claim c : claims.list(id)) {
    38	            if (!ClaimStatus.isOpen(c.getStatus())) continue;
    39	            Person p = byId.get(c.getPersonId());
    40	            if (p == null || !candidate.grade().equals(p.gradeOn(c.getDate()))) continue;
    41	            Rate rate = RateRepository.inForce(sheetRates, candidate.grade(), c.getDate(), c.getId());
    42	            String now = Dues.shown(c, rate == null ? null
    43	                    : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
    44	            String then = Dues.shown(c, Dues.of(c.getAmount(), pct, late.rounding(c.getRoundDate())),
    45	                    floor.on(c.getDate()), late);
    46	            BigDecimal before = now == null ? BigDecimal.ZERO.setScale(2) : new BigDecimal(now);
    47	            BigDecimal after = then == null ? BigDecimal.ZERO.setScale(2) : new BigDecimal(then);
    48	            if (now == null ? then == null : then != null && before.compareTo(after) == 0) continue;
    49	            count++;
    50	            diff = diff.add(after.subtract(before));
    51	        }
    52	        response.send(new RatePreview(count, diff.setScale(2).toPlainString()));
    53	    }
