   158	    private static Rate inForce(List<Rate> rates, String grade, String date, Long claimId) {
   159	        int top = rates.stream().mapToInt(Rate::level).max().orElse(0);
   160	        for (int level = 0; level <= top; level++) {
   161	            Rate found = null;
   162	            for (Rate listed : rates) {
   163	                Rate r = claimId == null ? listed : listed.forClaim(claimId);
   164	                if (r == null || r.level() != level || !r.grade().equals(grade) || (r.from() != null && r.from().compareTo(date) > 0)) continue;
   165	                if (found == null || (found.from() == null ? "" : found.from()).compareTo(r.from() == null ? "" : r.from()) < 0) found = r;
   166	            }
   167	            if (found != null && !found.endedBefore(date)) return found;
   168	        }
   169	        return null;
   170	    }
