   172	    /** Set the grade's rate from the from-date (null: from the beginning of time) through the to-date
   173	     *  (null: no end). When the grade already has a rate from that from-date, the one it replaces is kept
   174	     *  as an older version and the new one is the next version (the one in force). A from-date on or after
   175	     *  the sheet's today makes it forward-only: it applies only to claims added after now. */
   176	    public Rate set(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to, String user) {
   177	        String match = "sheet_id = ? AND grade = ? AND from_key = COALESCE(CAST(? AS DATE), DATE '0001-01-01')";
   178	        LocalDate today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId)
   179	                .stream().filter((d) -> d != null).findFirst().orElse(LocalDate.now());
   180	        Long claimsAfter = from == null || from.isBefore(today) ? null
   181	                : jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM claim", Long.class);
