   183	                + "SELECT sheet_id, grade, version, pct, from_date, to_date, set_by, set_at, claims_after FROM rate WHERE " + match,
   184	                sheetId, grade, from);
   185	        int version = 1 + jdbc.queryForList("SELECT version FROM rate WHERE " + match, Integer.class, sheetId, grade, from)
   186	                .stream().findFirst().orElse(0);
   187	        jdbc.update("DELETE FROM rate WHERE " + match, sheetId, grade, from);
   188	        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date, set_by, set_at, version, claims_after) "
   189	                + "VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?, ?)", sheetId, grade, pct, from, to, user, version, claimsAfter);
   190	        jdbc.update("INSERT INTO rate_history (sheet_id, grade, pct, from_date, to_date, on_date, version, claims_after) "
   191	                + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)",
   192	                sheetId, grade, pct, from, to, sheetId, version, claimsAfter);
   193	        return new Rate(sheetId, grade, pct.toPlainString(), from == null ? null : from.toString(),
   194	                to == null ? null : to.toString(), 0, version, claimsAfter, null);
   195	    }
