    31	    public java.util.List<String> descendants(String id) {
    32	        java.util.List<String> found = new java.util.ArrayList<>();
    33	        java.util.Set<String> seen = new java.util.HashSet<>(java.util.List.of(id));
    34	        for (int i = -1; i < found.size(); i++) {
    35	            String at = i < 0 ? id : found.get(i);
    36	            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting = 'parent' "
