    20	/**
    21	 * A request about a sheet carrying {@code shown-asof=<yyyy-MM-dd>} comes from a screen showing the sheet as
    22	 * of that date. A read (any GET, and loading the sheet) is answered from the sheet as it stood then
    23	 * ({@link AsOfStore}), with the date as its today; every change is refused (403) before anything is
    24	 * read or written, so nothing reaches the store or the audit file.
    25	 */
    26	@Component
    27	@Order(Ordered.HIGHEST_PRECEDENCE + 100)
    28	public class AsOfFilter extends OncePerRequestFilter {
    29	
    30	    private static final Pattern SHEET = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");
    31	
    32	    private final AsOfStore store;
    33	
    34	    public AsOfFilter(AsOfStore store) {
    35	        this.store = store;
    36	    }
    37	
    38	    @Override
    39	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
    40	            throws ServletException, IOException {
    41	        String asOf = request.getParameter("shown-asof");
    42	        Matcher sheet = SHEET.matcher(request.getRequestURI().substring(request.getContextPath().length()));
    43	        if (asOf == null || asOf.isBlank() || !sheet.matches()) {
    44	            chain.doFilter(request, response);
    45	            return;
    46	        }
    47	        boolean read = "GET".equals(request.getMethod())
    48	                || ("POST".equals(request.getMethod()) && "/open".equals(sheet.group(2)));
    49	        if (!read) {
    50	            refuse(response, HttpStatus.FORBIDDEN, "The sheet is shown as of a date: nothing can be changed");
    51	            return;
    52	        }
    53	        LocalDate date;
    54	        try {
    55	            date = LocalDate.parse(asOf.trim());
    56	        } catch (DateTimeParseException e) {
    57	            refuse(response, HttpStatus.BAD_REQUEST, "Not a date: " + asOf);
    58	            return;
    59	        }
    60	        String schema = store.view(UriUtils.decode(sheet.group(1), StandardCharsets.UTF_8).trim(), date);
    61	        AsOfView.enter(schema);
    62	        try {
    63	            chain.doFilter(request, response);
    64	        } finally {
    65	            AsOfView.leave();
    66	            store.drop(schema);
    67	        }
    68	    }
    69	
    70	    private static void refuse(HttpServletResponse response, HttpStatus status, String message) throws IOException {
    71	        response.setStatus(status.value());
    72	        response.setContentType("text/plain;charset=UTF-8");
    73	        response.getWriter().write(message);
    74	    }
    75	}
