   182	    /** Works something out from the sheet as of the date, as a request shown as of it would: on a thread of
   183	     *  its own, so it reads the view on connections of its own, outside the caller's transaction. */
   184	    public <T> T read(String sheetId, LocalDate asOf, java.util.function.Supplier<T> work) {
   185	        String schema = view(sheetId, asOf);
   186	        try {
   187	            java.util.concurrent.FutureTask<T> task = new java.util.concurrent.FutureTask<>(() -> {
   188	                AsOfView.enter(schema);
   189	                try {
   190	                    return work.get();
   191	                } finally {
   192	                    AsOfView.leave();
   193	                }
   194	            });
   195	            Thread thread = new Thread(task, "as-of-" + schema);
   196	            thread.start();
   197	            try {
   198	                return task.get();
   199	            } catch (InterruptedException e) {
   200	                Thread.currentThread().interrupt();
   201	                throw new IllegalStateException("Interrupted reading the sheet as of " + asOf, e);
   202	            } catch (java.util.concurrent.ExecutionException e) {
   203	                if (e.getCause() instanceof RuntimeException r) throw r;
   204	                throw new IllegalStateException("Could not read the sheet as of " + asOf, e.getCause());
   205	            }
   206	        } finally {
   207	            drop(schema);
   208	        }
   209	    }
