   211	    /** Drop a view's schema once its request is done. */
   212	    public synchronized void drop(String schema) {
   213	        try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
   214	            c.setAutoCommit(true);
   215	            s.execute("DROP SCHEMA IF EXISTS " + q(schema) + " CASCADE");
   216	        } catch (SQLException e) {
   217	            // left behind: it is never read again
   218	        }
   219	    }
