   223	        try (PreparedStatement ps = c.prepareStatement("SELECT created_by, today FROM PUBLIC.sheet WHERE id = ?")) {
   224	            ps.setString(1, sheetId);
   225	            try (ResultSet rs = ps.executeQuery()) {
   226	                return rs.next() ? new String[] { rs.getString(1), rs.getObject(2, LocalDate.class).toString() } : null;
