   279	    /** Copy the sheet's rows of every table from {@code source} (null: none) into a new schema. */
   280	    private void copy(Connection c, String source, String target, String sheetId) throws SQLException {
   281	        if (liveTables == null) liveTables = tables(c, LIVE);
   282	        List<String> tables = liveTables;
   283	        // A snapshot is a copy of every live table, all taken since the app started.
   284	        Set<String> inSource = source == null ? Set.of() : new HashSet<>(source.equals(LIVE) || source.startsWith("SNAP_") ? tables : tables(c, source));
   285	        String sheet = "'" + sheetId.replace("'", "''") + "'";
   286	        try (Statement s = c.createStatement()) {
   287	            s.execute("CREATE SCHEMA " + q(target));
   288	            for (String table : tables) {
   289	                boolean has = inSource.contains(table);
   290	                String from = q(has ? source : LIVE);
   291	                String where = has ? filter(c, table, from, sheet) : "FALSE";
   292	                s.execute("CREATE TABLE " + q(target) + "." + q(table) + " AS SELECT * FROM " + from + "."
   293	                        + q(table) + " WHERE " + where);
   294	            }
   295	        }
   296	    }
   297	
   298	    /** The condition picking the sheet's rows of a table. */
   299	    private String filter(Connection c, String table, String from, String sheet) throws SQLException {
   300	        if (table.equals("SHEET")) return "ID = " + sheet;
   301	        Set<String> columns = liveColumns.get(table);
   302	        if (columns == null) {
   303	            columns = columns(c, table);
   304	            liveColumns.put(table, columns);
   305	        }
   306	        if (columns.contains("SHEET_ID")) return "SHEET_ID = " + sheet;
   307	        for (String owner : List.of("PERIOD", "PERSON", "CLAIM")) {
   308	            if (columns.contains(owner + "_ID")) {
   309	                return owner + "_ID IN (SELECT ID FROM " + from + "." + owner + " WHERE SHEET_ID = " + sheet + ")";
   310	            }
   311	        }
   312	        return "TRUE";
   313	    }
   314	
   315	    private static List<String> tables(Connection c, String schema) throws SQLException {
   316	        List<String> tables = new ArrayList<>();
   317	        try (PreparedStatement ps = c.prepareStatement("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES "
   318	                + "WHERE TABLE_SCHEMA = ? AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_NAME")) {
   319	            ps.setString(1, schema);
   320	            try (ResultSet rs = ps.executeQuery()) {
   321	                while (rs.next()) {
   322	                    if (!SKIP.contains(rs.getString(1))) tables.add(rs.getString(1));
   323	                }
   324	            }
   325	        }
   326	        return tables;
   327	    }
   328	
   329	    private static Set<String> columns(Connection c, String table) throws SQLException {
   330	        Set<String> columns = new HashSet<>();
   331	        try (PreparedStatement ps = c.prepareStatement("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS "
   332	                + "WHERE TABLE_SCHEMA = ? AND TABLE_NAME = ?")) {
   333	            ps.setString(1, LIVE);
   334	            ps.setString(2, table);
   335	            try (ResultSet rs = ps.executeQuery()) {
   336	                while (rs.next()) columns.add(rs.getString(1));
   337	            }
   338	        }
   339	        return columns;
   340	    }
   341	
   342	    private static String q(String identifier) {
   343	        return "\"" + identifier.replace("\"", "\"\"") + "\"";
   344	    }
