    18	/**
    19	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
    20	 * so tests can assert side-effects by reading that file — the second test-assertion channel
    21	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
    22	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
    23	 *
    24	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
    25	 * SYNC) so a test reads the record immediately.
    26	 */
    27	@Service
    28	public class Audit {
    29	
    30	    /** The lines that only report figures: they never name a delegating steward. */
    31	    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");
    32	
    33	    private final Path file;
    34	
    35	    private final RoleRepository roles;
    36	
    37	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, RoleRepository roles) {
    38	        this.file = Path.of(path);
    39	        this.roles = roles;
    40	    }
    41	
    42	    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user
    43	     *  acting as a steward by delegation (the sheet's today inside its range) ends with
    44	     *  {@code for=<the steward who delegated>}. */
    45	    public synchronized void record(String entry) {
    46	        entry = entry + delegatedFor(entry);
    47	        try {
    48	            Path parent = file.toAbsolutePath().getParent();
    49	            if (parent != null) {
    50	                Files.createDirectories(parent);
    51	            }
    52	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
    53	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
    54	        } catch (IOException e) {
    55	            throw new UncheckedIOException(e);
    56	        }
    57	    }
    58	
    59	    /** " for=<steward>" when the line's user acts by delegation on its sheet; else "". */
    60	    private String delegatedFor(String entry) {
    61	        String[] fields = entry.split(" ");
    62	        if (FIGURES.contains(fields[0])) return "";
    63	        String sheet = null;
    64	        String by = null;
    65	        for (String field : fields) {
    66	            if (sheet == null && field.startsWith("sheet=")) sheet = field.substring("sheet=".length());
    67	            else if (by == null && field.startsWith("by=")) by = field.substring("by=".length());
    68	        }
    69	        if (sheet == null || by == null || by.isEmpty()) return "";
    70	        String steward = roles.delegatorOf(sheet, by);
    71	        return steward == null ? "" : " for=" + steward;
    72	    }
    73	
    74	    /** The sheet's lines exactly as the file holds them, newest first. With a name (case and
    75	     *  surrounding spaces ignored; blank: every line) only those carrying {@code name=<it>} or
    76	     *  {@code person=<it>}. Reads the file; keeps nothing of its own. */
    77	    public synchronized List<String> lines(String sheetId, String name) {
    78	        if (!Files.exists(file)) return List.of();
    79	        List<String> all;
    80	        try {
    81	            all = Files.readAllLines(file, StandardCharsets.UTF_8);
    82	        } catch (IOException e) {
    83	            throw new UncheckedIOException(e);
    84	        }
    85	        String sheetField = "sheet=" + sheetId;
    86	        String who = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
    87	        List<String> found = new ArrayList<>();
    88	        for (String line : all) {
    89	            if (!List.of(line.split(" ")).contains(sheetField)) continue;
    90	            if (!who.isEmpty() && !about(line, who)) continue;
    91	            found.add(line);
    92	        }
    93	        Collections.reverse(found);
    94	        return found;
    95	    }
    96	
    97	    /** A claim's timeline: the sheet's lines exactly as the file holds them, newest first, that carry
    98	     *  {@code number=<its number>}; for a claim with no number, those naming its person, amount and
    99	     *  date together (and no number, which would make them another claim's). */
   100	    public List<String> claimLines(String sheetId, String number, String person, String amount, String date) {
   101	        List<String> found = new ArrayList<>();
   102	        for (String line : lines(sheetId, null)) {
   103	            String padded = " " + line + " ";
   104	            boolean ours = number != null && !number.isBlank()
   105	                    ? padded.contains(" number=" + number + " ")
   106	                    : !padded.contains(" number=")
   107	                            && padded.contains(" person=" + person + " ")
   108	                            && padded.contains(" amount=" + amount + " ")
   109	                            && padded.contains(" date=" + date + " ");
   110	            if (ours) found.add(line);
   111	        }
   112	        return found;
   113	    }
   114	
   115	    /** Whether the line carries name=<who> or person=<who> (who: trimmed, lower case). */
   116	    private static boolean about(String line, String who) {
   117	        String lower = " " + line.toLowerCase(Locale.ROOT) + " ";
   118	        for (String key : List.of(" name=", " person=")) {
   119	            int at = lower.indexOf(key);
   120	            while (at >= 0) {
   121	                int start = at + key.length();
   122	                int end = start + who.length();
   123	                if (lower.startsWith(who, start) && end < lower.length() && lower.charAt(end) == ' ') return true;
   124	                at = lower.indexOf(key, at + 1);
   125	            }
   126	        }
   127	        return false;
   128	    }
   129	
   130	    /** Remove the audit file. */
   131	    public synchronized void clear() {
   132	        try {
   133	            Files.deleteIfExists(file);
   134	        } catch (IOException e) {
   135	            throw new UncheckedIOException(e);
   136	        }
   137	    }
   138	}
