    12	    private Dues() {
    13	    }
    14	
    15	    /** What a late charge goes by: the sheet's late percent by date (a charge goes by the one in force on each 30-day boundary) and its today (a claim's due-by is its own); the
    16	     *  sheet's policy date (its today when blank), which decides how a claim's live figures round; and
    17	     *  a claim's grace days (those of its person's grade in force on its date, as in force on it; 0: none); and
    18	     *  the sheet's rounding mode by date (half-up or half-even; none: the policy date decides). */
    19	    public record Late(DatedSetting pct, LocalDate today, LocalDate policy, ToIntFunction<Claim> grace, DatedSetting mode) {
    20	
    21	        /** The date a claim's lateness counts from: its due-by plus its grace days. It is overdue once
    22	         *  this is before the sheet's today. */
    23	        public LocalDate lateFrom(Claim claim) {
    24	            return LocalDate.parse(claim.getDueBy()).plusDays(grace.applyAsInt(claim));
    25	        }
    26	
    27	        /** How the live figures of a claim round by its round date ({@link Claim#getRoundDate}): by the
    28	         *  rounding mode in force on it, else half up before the policy date, half to even on or after it. */
    29	        public RoundingMode rounding(String roundDate) {
    30	            String m = mode == null ? null : mode.on(roundDate);
    31	            if ("half-up".equals(m)) return RoundingMode.HALF_UP;
    32	            if ("half-even".equals(m)) return RoundingMode.HALF_EVEN;
    33	            return LocalDate.parse(roundDate).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    34	        }
    35	    }
    36	
    37	    /** A claim's rate figure: an amount times a percent, divided by 100, rounded ({@code rounding}) to
    38	     *  two decimals (no floor: that is applied by {@link #shown}, before the late charge). */
    39	    public static String of(String amount, String pct, RoundingMode rounding) {
    40	        return new BigDecimal(amount).multiply(new BigDecimal(pct))
    41	                .divide(BigDecimal.valueOf(100), 2, rounding).toPlainString();
    42	    }
    43	
    44	    /** Whether a claim's amount makes it a correction: it is negative. */
    45	    public static boolean isCorrection(String amount) {
    46	        return new BigDecimal(amount).signum() < 0;
    47	    }
    48	
    49	    /** The late charge on a claim's figure: for each full 30 days its open (OPEN or PENDING) claim is past its
    50	     *  due-by (fixed when it was added) plus its grace days on the sheet's today, the late percent in force on that
    51	     *  boundary date (its due-by plus grace plus 30, 60, 90 ... days) of the figure plus the charges of
    52	     *  the boundaries before it (compounding), each rounded by the policy date to two decimals, added up;
    53	     *  none (0.00) when it is not overdue (a deferred claim never is), on a correction, or when it is waived. */
    54	    public static BigDecimal charge(Claim claim, String figure, Late late) {
    55	        BigDecimal total = BigDecimal.ZERO.setScale(2);
    56	        if (figure == null || isCorrection(claim.getAmount()) || !ClaimStatus.isOpen(claim.getStatus()) || claim.isDeferred() || claim.isWaived()) return total;
    57	        LocalDate dueBy = late.lateFrom(claim);
    58	        long periods = Math.max(0, ChronoUnit.DAYS.between(dueBy, late.today())) / 30;
    59	        RoundingMode rounding = late.rounding(claim.getRoundDate());
    60	        for (long k = 1; k <= periods; k++) {
    61	            String pct = late.pct().on(dueBy.plusDays(30 * k).toString());
    62	            if (pct == null) continue;
    63	            total = total.add(new BigDecimal(figure).add(total).multiply(new BigDecimal(pct))
    64	                    .divide(BigDecimal.valueOf(100), 2, rounding));
    65	        }
    66	        return total;
    67	    }
    68	
    69	    /** The due a claim shows: the one fixed when settled, else the one a statement bound it to (its due as
    70	     *  shown then, floor and late charge included; null: none), else {@code live} (null: none) raised to at
    71	     *  least {@code floor}, the sheet's floor in force on the claim's date (null: none; a correction has no
    72	     *  floor), with the late charge on that floored figure on the sheet's today added on top. */
    73	    public static String shown(Claim claim, String live, String floor, Late late) {
    74	        if (claim.getSettledDue() != null) return claim.getSettledDue();
    75	        if (claim.isStated()) return claim.getStatedDue();
    76	        if (live == null) return null;
    77	        BigDecimal floored = new BigDecimal(live);
    78	        if (floor != null && !isCorrection(claim.getAmount())) floored = floored.max(new BigDecimal(floor).setScale(2));
    79	        String figure = floored.toPlainString();
    80	        return floored.add(charge(claim, figure, late)).toPlainString();
    81	    }
    82	}

